using System.Net;
using System.Text.Json;
using Htt.Host.Api;
using Htt.Host.Api.MasterData;
using Htt.Infrastructure;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class CrmDraftTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();private static long V(JsonElement x)=>x.GetProperty("version").GetInt64();
 private async Task<(Guid Customer,string Sales,string Office,Guid Membership)> People(HttpClient admin)
 {var customer=await Create(admin,"/customers",new CustomerDraft(Code(),"Existing client",null));var sales=await Staff(db,"SALES");var office=await Staff(db,"OFFICE");await S("INSERT INTO identity.customer_assignments(company_id,membership_id,customer_id)VALUES(@c,@m,@customer)",("c",db.Company),("m",sales.Membership),("customer",customer));return(customer,sales.Subject,office.Subject,sales.Membership);}
 private static Task<JsonElement> Draft(HttpClient c,string kind,Guid? customer,CrmDraftData? data=null)=>Make(c,new(Guid.NewGuid(),kind,customer,data??new("Draft "+Code(),Code(),Email:"a"+Code()+"@example.test",Phone:"0412 345 678",AddressLine1:"10 Test Street",State:"NSW",Postcode:"2000")));
 private static async Task<JsonElement> Make(HttpClient c,CrmDraftInput x)=>await Expect(await Send(c,HttpMethod.Post,"/crm/drafts",x),HttpStatusCode.Created);
 private static Task<HttpResponseMessage> Submit(HttpClient c,JsonElement d,string? key=null)=>Send(c,HttpMethod.Post,$"/crm/drafts/{Id(d)}/submit",version:V(d),key:key);
 private static Task<HttpResponseMessage> Review(HttpClient c,JsonElement d,bool approve=true,string? key=null)=>Send(c,HttpMethod.Post,$"/crm/drafts/{Id(d)}/review",new CrmReview(approve,"Office verified"),V(d),key);
 private static async Task<Guid> Device(HttpClient c){var id=Guid.NewGuid();await Expect(await Send(c,HttpMethod.Post,"/crm/mobile/devices",new MobileDevice(id)),HttpStatusCode.Created);return id;}
 private static Task<HttpResponseMessage> Push(HttpClient c,Guid device,MobileOperation x,string? key=null)=>Send(c,HttpMethod.Post,$"/crm/mobile/devices/{device}/operations",x,key:key);
 [Theory][InlineData("CUSTOMER")][InlineData("BRANCH")][InlineData("CONTACT")]
 public async Task Sales_draft_requires_independent_office_approval_to_create_formal_data(string kind)
 {await using var api=new TestApi(db);using var admin=api.Authenticated();var p=await People(admin);using var sales=api.Authenticated(p.Sales);using var office=api.Authenticated(p.Office);var d=await Draft(sales,kind,kind=="CUSTOMER"?null:p.Customer);d=await Expect(await Submit(sales,d),HttpStatusCode.OK);d=await Expect(await Review(office,d),HttpStatusCode.OK);Assert.Equal("APPROVED",d.GetProperty("state").GetString());var fid=d.GetProperty("formalId").GetGuid();var table=kind switch{"CUSTOMER"=>"customers","BRANCH"=>"customer_branches",_=>"contacts"};Assert.Equal(1L,await S($"SELECT count(*)FROM crm.{table} WHERE company_id=@c AND id=@id",("c",db.Company),("id",fid)));if(kind=="CUSTOMER"){Assert.Equal(1L,await S("SELECT count(*)FROM crm.customer_credit_exposures WHERE company_id=@c AND customer_id=@id",("c",db.Company),("id",fid)));Assert.Equal(0m,await S("SELECT credit_limit FROM crm.customers WHERE company_id=@c AND id=@id",("c",db.Company),("id",fid)));Assert.Equal(30,await S("SELECT payment_terms_days FROM crm.customers WHERE company_id=@c AND id=@id",("c",db.Company),("id",fid)));Assert.Equal(1L,await S("SELECT count(*)FROM identity.customer_assignments WHERE company_id=@c AND membership_id=@m AND customer_id=@id",("c",db.Company),("m",p.Membership),("id",fid)));}}
 [Theory][InlineData(true)][InlineData(false)]public async Task Concurrent_review_creates_one_formal_contact(bool sameKey)
 {await using var api=new TestApi(db);using var admin=api.Authenticated();var p=await People(admin);using var sales=api.Authenticated(p.Sales);using var office=api.Authenticated(p.Office);var d=await Draft(sales,"CONTACT",p.Customer);d=await Expect(await Submit(sales,d),HttpStatusCode.OK);var key=Code();var all=await Task.WhenAll(Review(office,d,key:key),Review(office,d,key:sameKey?key:Code()));Assert.Equal(sameKey?2:1,all.Count(r=>r.StatusCode==HttpStatusCode.OK));if(!sameKey)Assert.Single(all,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.Equal(1L,await S("SELECT count(*)FROM crm.contacts WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Owner_scope_other_sales_company_and_self_approval_are_checked()
 {await using var api=new TestApi(db);using var admin=api.Authenticated();var p=await People(admin);using var sales=api.Authenticated(p.Sales);var other=await Staff(db,"SALES");using var outside=api.Authenticated(other.Subject);var d=await Draft(sales,"CONTACT",p.Customer);await Expect(await Send(outside,HttpMethod.Get,$"/crm/drafts/{Id(d)}"),HttpStatusCode.Forbidden);using var otherCompany=api.Authenticated(company:db.OtherCompany);await Expect(await Send(otherCompany,HttpMethod.Get,$"/crm/drafts/{Id(d)}"),HttpStatusCode.NotFound);await Expect(await Review(sales,d),HttpStatusCode.Forbidden);var own=await Draft(admin,"CUSTOMER",null);own=await Expect(await Submit(admin,own),HttpStatusCode.OK);await Expect(await Review(admin,own),HttpStatusCode.Forbidden);}
 [Fact]public async Task Duplicate_preview_prevents_duplicate_approval_without_automatic_merging()
 {await using var api=new TestApi(db);using var admin=api.Authenticated();var p=await People(admin);using var sales=api.Authenticated(p.Sales);using var office=api.Authenticated(p.Office);var body=new CrmDraftData("Same person",Email:"same@example.test");var a=await Draft(sales,"CONTACT",p.Customer,body);a=await Expect(await Submit(sales,a),HttpStatusCode.OK);await Expect(await Review(office,a),HttpStatusCode.OK);var b=await Draft(sales,"CONTACT",p.Customer,body);Assert.Single((await Get(sales,$"/crm/drafts/{Id(b)}/duplicates")).EnumerateArray());b=await Expect(await Submit(sales,b),HttpStatusCode.OK);await Expect(await Review(office,b),HttpStatusCode.Conflict);await Expect(await Review(office,b,false),HttpStatusCode.OK);}
 [Fact]public async Task Contacts_import_normalizes_previews_and_confirms_selected_rows_as_drafts_only()
 {await using var api=new TestApi(db);using var admin=api.Authenticated();var p=await People(admin);using var sales=api.Authenticated(p.Sales);var input=new ContactImport(p.Customer,"device-consent-selection-1",[new("Selected",Email:"ONE@EXAMPLE.TEST",Phone:"0412 345 678"),new("Duplicate",Email:"one@example.test",Phone:"0412 345 678")]);var preview=await Expect(await Send(sales,HttpMethod.Post,"/crm/contact-imports",input),HttpStatusCode.Created);Assert.Equal("+61412345678",preview.GetProperty("rows")[0].GetProperty("data").GetProperty("phone").GetString());Assert.True(preview.GetProperty("rows")[1].GetProperty("withinBatchDuplicate").GetBoolean());var id=Id(preview);await Expect(await Send(sales,HttpMethod.Post,$"/crm/contact-imports/{id}/confirm",new ContactImportConfirmation([1])),HttpStatusCode.Conflict);var key=Code();var a=await Expect(await Send(sales,HttpMethod.Post,$"/crm/contact-imports/{id}/confirm",new ContactImportConfirmation([0]),key:key),HttpStatusCode.Created);var b=await Expect(await Send(sales,HttpMethod.Post,$"/crm/contact-imports/{id}/confirm",new ContactImportConfirmation([0]),key:key),HttpStatusCode.Created);Assert.True(JsonElement.DeepEquals(a,b));Assert.Equal(1L,await S("SELECT count(*)FROM crm.mobile_drafts WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM crm.contacts WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Device_operation_replay_is_stable_across_HTTP_keys_and_changed_payload_is_rejected()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=await Device(c);var op=new MobileOperation(Guid.NewGuid(),1,Guid.NewGuid(),"CREATE",Kind:"CUSTOMER",Data:new("Mobile customer",Code()));var a=await Expect(await Push(c,device,op),HttpStatusCode.OK);var b=await Expect(await Push(c,device,op),HttpStatusCode.OK);Assert.True(JsonElement.DeepEquals(a,b));await Expect(await Push(c,device,op with{Data=new("Changed",Code())}),HttpStatusCode.Conflict);Assert.Equal(1L,await S("SELECT count(*)FROM crm.mobile_drafts WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Sequence_gaps_conflicts_and_tombstones_do_not_resurrect_deleted_drafts()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=await Device(c);var id=Guid.NewGuid();await Expect(await Push(c,device,new(Guid.NewGuid(),2,id,"CREATE",Kind:"CUSTOMER",Data:new("Gap",Code()))),HttpStatusCode.Conflict);var create=new MobileOperation(Guid.NewGuid(),1,id,"CREATE",Kind:"CUSTOMER",Data:new("Offline",Code()));await Expect(await Push(c,device,create),HttpStatusCode.OK);var conflict=await Expect(await Push(c,device,new(Guid.NewGuid(),2,id,"UPDATE",99,Data:new("Old",Code()))),HttpStatusCode.OK);Assert.Equal("CONFLICT",conflict.GetProperty("status").GetString());await Expect(await Push(c,device,new(Guid.NewGuid(),3,id,"DELETE",1)),HttpStatusCode.OK);var restore=await Expect(await Push(c,device,new(Guid.NewGuid(),4,id,"UPDATE",2,Data:new("Zombie",Code()))),HttpStatusCode.OK);Assert.Equal("CONFLICT",restore.GetProperty("status").GetString());var changes=await Get(c,$"/crm/mobile/devices/{device}/changes?after=0");Assert.Equal(2,changes.GetProperty("items").GetArrayLength());Assert.True(changes.GetProperty("items")[1].GetProperty("tombstone").GetBoolean());Assert.Equal(JsonValueKind.Null,changes.GetProperty("items")[1].GetProperty("draft").GetProperty("data").ValueKind);}
 [Fact]public async Task Revoked_customer_scope_blocks_cached_push_and_invalidates_incremental_cursor()
 {await using var api=new TestApi(db);using var admin=api.Authenticated();var p=await People(admin);using var sales=api.Authenticated(p.Sales);var device=await Device(sales);var op=new MobileOperation(Guid.NewGuid(),1,Guid.NewGuid(),"CREATE",Kind:"CONTACT",CustomerId:p.Customer,Data:new("Owned"));var key=Code();await Expect(await Push(sales,device,op,key),HttpStatusCode.OK);var pull=await Get(sales,$"/crm/mobile/devices/{device}/changes?after=0");await S("DELETE FROM identity.customer_assignments WHERE company_id=@c AND membership_id=@m",("c",db.Company),("m",p.Membership));await Expect(await Push(sales,device,op,key),HttpStatusCode.NotFound);await Expect(await Send(sales,HttpMethod.Get,$"/crm/mobile/devices/{device}/changes?after=1&auth={pull.GetProperty("auth").GetString()}"),HttpStatusCode.Conflict);Assert.Empty((await Get(sales,$"/crm/mobile/devices/{device}/changes?after=0")).GetProperty("items").EnumerateArray());}
 [Fact]public async Task Device_cannot_be_claimed_or_pulled_by_another_actor()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Device(c);var staff=await Staff(db,"SALES");using var other=api.Authenticated(staff.Subject);await Expect(await Send(other,HttpMethod.Post,"/crm/mobile/devices",new MobileDevice(d)),HttpStatusCode.Forbidden);await Expect(await Send(other,HttpMethod.Get,$"/crm/mobile/devices/{d}/changes"),HttpStatusCode.Forbidden);}
 [Theory][InlineData("WAREHOUSE")][InlineData("FINANCE")][InlineData("PROCUREMENT")]
 public async Task Non_CRM_roles_cannot_capture_drafts_or_devices(string role)
 {await using var api=new TestApi(db);var staff=await Staff(db,role);using var c=api.Authenticated(staff.Subject);await Expect(await Send(c,HttpMethod.Post,"/crm/mobile/devices",new MobileDevice(Guid.NewGuid())),HttpStatusCode.Forbidden);await Expect(await Send(c,HttpMethod.Post,"/crm/drafts",new CrmDraftInput(Guid.NewGuid(),"CUSTOMER",null,new("Denied",Code()))),HttpStatusCode.Forbidden);}
 [Theory][InlineData("create")][InlineData("review")][InlineData("push")][InlineData("import_confirm")]
 public async Task Audit_failure_rolls_back_CRM_master_feed_operation_and_same_key_can_retry(string action)
 {await using var api=new TestApi(db);using var admin=api.Authenticated();var p=await People(admin);using var sales=api.Authenticated(p.Sales);using var office=api.Authenticated(p.Office);var input=new CrmDraftInput(Guid.NewGuid(),"CONTACT",p.Customer,new("Atomic",Email:"atomic@example.test"));JsonElement d=default;Guid dev=Guid.Empty;Guid import=Guid.Empty;if(action=="review"){d=await Make(sales,input);d=await Expect(await Submit(sales,d),HttpStatusCode.OK);}if(action=="push")dev=await Device(sales);if(action=="import_confirm")import=Id(await Expect(await Send(sales,HttpMethod.Post,"/crm/contact-imports",new ContactImport(p.Customer,"consent",[input.Data])),HttpStatusCode.Created));var key=Code();var op=new MobileOperation(Guid.NewGuid(),1,input.Id,"CREATE",Kind:"CONTACT",CustomerId:p.Customer,Data:input.Data);Task<HttpResponseMessage> Run()=>action switch{"create"=>Send(sales,HttpMethod.Post,"/crm/drafts",input,key:key),"review"=>Review(office,d,key:key),"push"=>Push(sales,dev,op,key),_=>Send(sales,HttpMethod.Post,$"/crm/contact-imports/{import}/confirm",new ContactImportConfirmation([0]),key:key)};var before=await S("SELECT count(*)FROM crm.mobile_changes WHERE company_id=@c",("c",db.Company));await S($"CREATE FUNCTION crm.test_c04_fail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='crm.{action}'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_c04_fail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION crm.test_c04_fail()");try{await Expect(await Run(),HttpStatusCode.UnprocessableEntity);Assert.Equal(before,await S("SELECT count(*)FROM crm.mobile_changes WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM crm.contacts WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM crm.mobile_operations WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER test_c04_fail ON platform.audit_events;DROP FUNCTION crm.test_c04_fail()");}await Expect(await Run(),action is"create"or"import_confirm"?HttpStatusCode.Created:HttpStatusCode.OK);}

 [Theory][InlineData(true)][InlineData(false)]public async Task Concurrent_device_replay_applies_exactly_one_draft(bool sameOperation)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=await Device(c);var op=new MobileOperation(Guid.NewGuid(),1,Guid.NewGuid(),"CREATE",Kind:"CUSTOMER",Data:new("Concurrent",Code()));var all=await Task.WhenAll(Push(c,device,op),Push(c,device,sameOperation?op:op with{OperationId=Guid.NewGuid(),Id=Guid.NewGuid()}));Assert.Equal(sameOperation?2:1,all.Count(r=>r.StatusCode==HttpStatusCode.OK));if(!sameOperation)Assert.Single(all,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.Equal(1L,await S("SELECT count(*)FROM crm.mobile_operations WHERE company_id=@c",("c",db.Company)));Assert.Equal(1L,await S("SELECT count(*)FROM crm.mobile_changes WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Revoked_device_cannot_register_replay_pull_or_write()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=Guid.NewGuid();var key=Code();await Expect(await Send(c,HttpMethod.Post,"/crm/mobile/devices",new MobileDevice(device),key:key),HttpStatusCode.Created);var revokeKey=Code();await Expect(await Send(c,HttpMethod.Delete,$"/crm/mobile/devices/{device}",key:revokeKey),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Delete,$"/crm/mobile/devices/{device}",key:revokeKey),HttpStatusCode.OK);await Expect(await Send(c,HttpMethod.Post,"/crm/mobile/devices",new MobileDevice(device),key:key),HttpStatusCode.Forbidden);await Expect(await Send(c,HttpMethod.Get,$"/crm/mobile/devices/{device}/changes"),HttpStatusCode.Forbidden);await Expect(await Push(c,device,new(Guid.NewGuid(),1,Guid.NewGuid(),"CREATE",Kind:"CUSTOMER",Data:new("No",Code()))),HttpStatusCode.Forbidden);}
 [Fact]public async Task Cursor_ahead_and_non_CRM_offline_operations_are_rejected()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=await Device(c);await Expect(await Send(c,HttpMethod.Get,$"/crm/mobile/devices/{device}/changes?after=999&auth=invalid"),HttpStatusCode.Conflict);await Expect(await Push(c,device,new(Guid.NewGuid(),1,Guid.NewGuid(),"POST_INVOICE")),HttpStatusCode.UnprocessableEntity);}
 [Fact]public async Task Sync_sequence_waits_for_earlier_transaction_commit_and_returns_both_changes()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=await Device(c);await using var con=new NpgsqlConnection(db.Owner);await con.OpenAsync();await using var tx=await con.BeginTransactionAsync();await using(var cmd=new NpgsqlCommand("SELECT set_config('htt.company_id',@c,true),set_config('htt.actor_id',@actor,true)",con,tx)){cmd.Parameters.AddWithValue("c",db.Company.ToString());cmd.Parameters.AddWithValue("actor",db.Actor.ToString());await cmd.ExecuteNonQueryAsync();}var first=Guid.NewGuid();await using(var cmd=new NpgsqlCommand("SELECT crm.create_mobile_draft(@id,'CUSTOMER',NULL,@data::jsonb)",con,tx)){cmd.Parameters.AddWithValue("id",first);cmd.Parameters.AddWithValue("data",JsonSerializer.Serialize(new{name="First commit",code=Code().ToUpperInvariant()}));await cmd.ExecuteScalarAsync();}var later=Send(c,HttpMethod.Post,"/crm/drafts",new CrmDraftInput(Guid.NewGuid(),"CUSTOMER",null,new("Second commit",Code())));await Task.Delay(75);Assert.False(later.IsCompleted);await tx.CommitAsync();await Expect(await later,HttpStatusCode.Created);var page=await Get(c,$"/crm/mobile/devices/{device}/changes?after=0&pageSize=1");Assert.Equal(first,page.GetProperty("items")[0].GetProperty("draft").GetProperty("id").GetGuid());var next=await Get(c,$"/crm/mobile/devices/{device}/changes?after={page.GetProperty("nextSequence").GetInt64()}&auth={page.GetProperty("auth").GetString()}");Assert.Single(next.GetProperty("items").EnumerateArray());Assert.False(next.GetProperty("hasMore").GetBoolean());}
 [Fact]public async Task App_cannot_mutate_sync_facts_or_read_private_seed_functions()
 {await using var s=await db.SessionAsync();await using var cmd=new NpgsqlCommand("DELETE FROM crm.mobile_changes",s.Connection,s.Transaction);Assert.Equal("42501",(await Assert.ThrowsAsync<PostgresException>(()=>cmd.ExecuteNonQueryAsync())).SqlState);}

 [Fact]public async Task Expired_and_reset_cursor_require_fresh_initial_sync()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var device=await Device(c);await Draft(c,"CUSTOMER",null);var first=await Get(c,$"/crm/mobile/devices/{device}/changes?after=0");var cursor=first.GetProperty("auth").GetString();await S("UPDATE crm.mobile_devices SET cursor_expires_at=now()-interval '1 second'WHERE company_id=@c AND id=@id",("c",db.Company),("id",device));await Expect(await Send(c,HttpMethod.Get,$"/crm/mobile/devices/{device}/changes?after=1&auth={cursor}"),HttpStatusCode.Conflict);var reset=await Get(c,$"/crm/mobile/devices/{device}/changes?after=0");Assert.NotEqual(cursor,reset.GetProperty("auth").GetString());await Expect(await Send(c,HttpMethod.Get,$"/crm/mobile/devices/{device}/changes?after=1&auth={cursor}"),HttpStatusCode.Conflict);}

 [Fact]public async Task Create_collision_does_not_leak_another_actors_draft_version()
 {await using var api=new TestApi(db);using var admin=api.Authenticated();var owned=await Draft(admin,"CUSTOMER",null);var staff=await Staff(db,"SALES");using var other=api.Authenticated(staff.Subject);var device=await Device(other);var result=await Expect(await Push(other,device,new(Guid.NewGuid(),1,Id(owned),"CREATE",Kind:"CUSTOMER",Data:new("Guess",Code()))),HttpStatusCode.OK);Assert.Equal("CONFLICT",result.GetProperty("status").GetString());Assert.Equal(JsonValueKind.Null,result.GetProperty("serverVersion").ValueKind);Assert.False(result.TryGetProperty("draft",out _));}
}
